<script setup lang="ts">
import {computed,ref,reactive,onMounted,inject,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {http,allRows} from '../api/http'
import {auth,clearAuth} from '../stores/auth'
import {useRouter} from 'vue-router'
import {roles} from '../router/v3menus'
import V3Business from '../components/V3Business.vue'
import V3Dashboard from '../components/V3Dashboard.vue'
import V3Home from '../components/V3Home.vue'
import EmployeeLifecycle from '../components/EmployeeLifecycle.vue'
import EmployeeDetails from '../components/EmployeeDetails.vue'
const props=defineProps<{mode:string;title:string}>(),router=useRouter()
const rows=ref<any[]>([]),departments=ref<any[]>([]),positions=ref<any[]>([]),accounts=ref<any[]>([]),profile=ref<any>(null)
const busy=ref(false),total=ref(0),page=ref(1),search=ref(''),department=ref<number>(),status=ref(''),roleFilter=ref(''),activeFilter=ref(''),positionFilter=ref<number>(),employeeNo=ref('')
const bootstrapStatus=ref<any>({}),dialog=ref(false),kind=ref(''),editId=ref<number>(),formRef=ref<any>(),form=reactive<any>({}),receipt=ref<any[]>([]),detail=ref<any>(null)
const selectedDepartment=ref<number>(),selectedSupervisor=ref<number>()
const isAdmin=computed(()=>props.mode.startsWith('/admin/')),isEmployees=computed(()=>props.mode==='/hr/employees'),isUsers=computed(()=>['/admin/users','/admin/departed-users'].includes(props.mode))
const eligiblePositions=computed(()=>positions.value.filter(p=>p.department_id===form.department_id&&(p.is_active||p.id===form.position_id)))
const candidates=computed(()=>accounts.value.filter(u=>u.department_id===selectedDepartment.value&&u.is_active&&u.employment_status==='ACTIVE'))
const active=inject<any>('workspace-active',ref(true))
const required=(label:string)=>[{required:true,message:`请填写${label}`,trigger:'blur'}]
function resetFilters(){page.value=1;load()}
async function metadata(){departments.value=(await http.get('/departments')).data;positions.value=await allRows('/positions')}
async function load(){
 busy.value=true
 try{
  await metadata()
  const params:any={page:page.value,page_size:20,search:search.value||undefined,department_id:department.value,status:status.value||undefined,employee_no:employeeNo.value||undefined,position_id:positionFilter.value,role:roleFilter.value||undefined,is_active:activeFilter.value||undefined}
  let result:any
  if(isEmployees.value)result=await http.get('/employees',{params})
  else if(isUsers.value)result=await http.get(props.mode,{params:{...params,status:undefined,employee_no:undefined,position_id:undefined}})
  else if(props.mode==='/hr/positions')result=await http.get('/positions',{params:{page:page.value,page_size:20,department_id:department.value}})
  else if(props.mode.includes('departments')||props.mode==='/admin/supervisors')result={data:departments.value,total:4}
  else if(props.mode==='/admin/audit-logs')result=await http.get('/admin/audit-logs',{params:{page:page.value,page_size:20}})
  else if(props.mode==='/admin/home'||props.mode==='/admin/bootstrap-hr'){
    bootstrapStatus.value=(await http.get('/bootstrap/status')).data
    accounts.value=await allRows('/admin/users');result={data:accounts.value,total:accounts.value.length}
  }else if(props.mode==='/my/profile'||props.mode==='/home')profile.value=(await http.get('/me/employee')).data
  if(result){rows.value=result.data;total.value=result.total||result.data.length}
  if(props.mode==='/admin/supervisors')accounts.value=await allRows('/admin/users')
 }finally{busy.value=false}
}
onMounted(load)
watch(active,(v:boolean)=>{if(v)load()})
function open(type:string,row?:any){
 kind.value=type;editId.value=row?.id;Object.keys(form).forEach(k=>delete form[k])
 Object.assign(form,type==='password'?{old_password:'',new_password:'',confirm_password:''}:type==='position'?{code:'',name:'',department_id:undefined,grade:'L1',is_active:true,description:''}:type==='role'?{role:row.role}:type==='username'?{username:row.username}:type==='reset'?{new_password:''}:type==='disable'?{reason:''}:{employee_no:'',name:'',department_id:undefined,position_id:undefined,hire_date:'',phone:'',base_salary:'0.00',remarks:'',position_name:'人事负责人',grade:'L3'})
 if(row&&['employee','position'].includes(type))for(const k of Object.keys(form))if(k in row)form[k]=row[k]
 dialog.value=true
}
function employeePayload(){return Object.fromEntries(['employee_no','name','department_id','position_id','hire_date','phone','remarks','base_salary'].map(k=>[k,form[k]||(['phone','remarks'].includes(k)?null:form[k])]))}
async function submit(){
 if(!await formRef.value?.validate().catch(()=>false))return
 const password=kind.value==='password'||kind.value==='reset'
 if(password&&(!/[A-Z]/.test(form.new_password)||!/[a-z]/.test(form.new_password)||!/[0-9]/.test(form.new_password)||form.new_password.length>128)){ElMessage.error('新密码须含大写字母、小写字母和数字，最多128字符');return}
 if(kind.value==='password'&&form.new_password!==form.confirm_password){ElMessage.error('两次新密码不一致');return}
 let r:any
 if(kind.value==='bootstrap')r=await http.post('/admin/bootstrap-first-hr',{...employeePayload(),position_id:form.position_id||null,position_name:form.position_name,grade:form.grade})
 else if(kind.value==='employee')r=editId.value?await http.patch(`/employees/${editId.value}`,employeePayload()):await http.post('/employees',employeePayload())
 else if(kind.value==='position'){const payload=Object.fromEntries(['code','name','department_id','grade','is_active','description'].map(k=>[k,form[k]]));r=editId.value?await http.patch(`/positions/${editId.value}`,payload):await http.post('/positions',payload)}
 else if(kind.value==='role'||kind.value==='username')r=await http.patch(`/admin/users/${editId.value}/${kind.value}`,form)
 else if(kind.value==='reset')r=await http.post(`/admin/users/${editId.value}/reset-password`,form)
 else if(kind.value==='disable')r=await http.post(`/admin/users/${editId.value}/disable`,form)
 else if(kind.value==='password'){await http.post('/auth/change-password',form);dialog.value=false;clearAuth();router.replace('/login');ElMessage.success('密码已更新，请重新登录');return}
 dialog.value=false;ElMessage.success(r?.message||'保存成功');await load()
}
async function enable(row:any){await http.post(`/admin/users/${row.id}/enable`);ElMessage.success('账号已启用');load()}
async function assign(){if(!selectedDepartment.value||!selectedSupervisor.value)return;await http.put(`/admin/departments/${selectedDepartment.value}/supervisor`,{user_id:selectedSupervisor.value});ElMessage.success('已指派主管');load()}
async function unassign(row:any){await http.delete(`/admin/departments/${row.id}/supervisor`);load()}
async function recover(){if(!form.employee_id)return;await http.post('/admin/recover-hr',{employee_id:form.employee_id});ElMessage.success('HR 已恢复');load()}
async function download(path:string){const response=await http.get(path,{responseType:'blob',params:{search:search.value||undefined,employee_no:employeeNo.value||undefined,department_id:department.value,position_id:positionFilter.value,status:status.value||undefined}});const url=URL.createObjectURL(response as unknown as Blob);const a=document.createElement('a');a.href=url;a.download=path.includes('template')?'员工导入模板.xlsx':'员工档案.xlsx';a.click();URL.revokeObjectURL(url)}
async function upload(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.length)return;const data=new FormData();data.append('file',input.files[0]);try{receipt.value=(await http.post('/employees/import',data)).data;await load()}finally{input.value=''}}
async function showDepartment(row:any){detail.value={kind:'department',title:row.name,data:(await http.get(`/departments/${row.id}/employees`)).data}}
async function showUser(row:any){detail.value={kind:'history',title:`${row.username} · 账号历史`,data:(await http.get(`/admin/users/${row.id}`)).data.employment_events}}
</script>
<template><main v-loading="busy"><div class="page-title"><div><div class="eyebrow">MANSHI · PEOPLE</div><h1>{{title}}</h1><p>满氏吉他制琴有限公司 · 人员与组织协作</p></div><el-button @click="load">刷新数据</el-button></div>
<template v-if="mode==='/admin/home'"><el-alert v-if="!bootstrapStatus.has_active_hr" title="尚无可用 HR，请先初始化真实 HR 员工" type="warning" :closable="false" show-icon/><div class="v3-cards"><el-card><span>账号总数</span><strong>{{accounts.length}}</strong></el-card><el-card v-for="(label,key) in roles" :key="key"><span>{{label}}</span><strong>{{accounts.filter(u=>u.role===key).length}}</strong></el-card></div><el-button v-if="!bootstrapStatus.has_active_hr" type="primary" @click="router.push('/admin/bootstrap-hr')">初始化首位 HR</el-button><p class="v3-note">部门主管暂未预设。HR 和主管均从真实员工账号授权产生。</p></template>
<template v-else-if="mode==='/admin/bootstrap-hr'"><el-card><h3>{{bootstrapStatus.has_active_hr?'HR 已可用':'初始化／恢复 HR 管理员可用性'}}</h3><p class="v3-note">填写真实员工档案后，系统在同一事务内建立姓名账号并授予 HR。初始密码 Aa123。已有可用 HR 时关闭此入口。</p><el-button type="primary" :disabled="bootstrapStatus.has_active_hr" @click="open('bootstrap')">初始化首位 HR</el-button><div v-if="!bootstrapStatus.has_active_hr" class="v3-section"><el-select v-model="form.employee_id" placeholder="选择现有在职员工" style="width:260px"><el-option v-for="u in accounts.filter(u=>u.employee_id&&u.employment_status==='ACTIVE')" :key="u.id" :value="u.employee_id" :label="`${u.name} · ${u.employee_no}`"/></el-select><el-button @click="recover">授予 HR 并恢复可用</el-button></div></el-card></template>
<template v-else-if="mode==='/account'"><el-card><h3>{{auth.user?.username}}</h3><p>角色：{{roles[auth.user?.role]}}</p><p class="v3-note">密码需同时含 ASCII 大写字母、小写字母和数字，最多128字符。修改后所有会话失效，需重新登录。</p><el-button type="primary" @click="open('password')">修改密码</el-button></el-card></template>
<template v-else-if="mode==='/my/profile'||mode==='/home'"><el-card v-if="profile"><h2>{{profile.name}}</h2><el-descriptions :column="2" border><el-descriptions-item label="工号">{{profile.employee_no}}</el-descriptions-item><el-descriptions-item label="登录名">{{profile.account_username}}</el-descriptions-item><el-descriptions-item label="部门">{{profile.department_name}}</el-descriptions-item><el-descriptions-item label="职位／职级">{{profile.position_name}} / {{profile.grade}}</el-descriptions-item><el-descriptions-item label="入职日期">{{profile.hire_date}}</el-descriptions-item><el-descriptions-item label="电话">{{profile.phone||'—'}}</el-descriptions-item><el-descriptions-item label="税前月基本工资（元）">{{profile.base_salary||'0.00'}}</el-descriptions-item></el-descriptions></el-card><V3Home v-if="mode==='/home'"/><div v-if="mode==='/home'" class="v3-section"><el-button @click="router.push('/my/attendance')">我的打卡</el-button><el-button @click="router.push('/my/leaves')">我的请假</el-button></div></template>
<template v-else-if="mode==='/hr/departments'||mode==='/admin/supervisors'"><el-alert title="公司固定四部门；部门名称与编码不提供修改入口" :closable="false"/><el-card v-if="mode==='/admin/supervisors'" class="v3-section"><div class="v3-toolbar"><el-select v-model="selectedDepartment" placeholder="选择部门" @change="selectedSupervisor=undefined"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select><el-select v-model="selectedSupervisor" placeholder="本部门在职员工"><el-option v-for="u in candidates" :key="u.id" :value="u.id" :label="`${u.name} · ${u.employee_no}`"/></el-select><el-button type="primary" @click="assign">指派主管</el-button></div></el-card><el-table :data="rows" class="v3-section"><el-table-column prop="code" label="部门编码"/><el-table-column prop="name" label="部门名称"/><el-table-column prop="active_count" label="在职人数"/><el-table-column prop="position_count" label="职位数量"/><el-table-column label="主管"><template #default="{row}">{{row.supervisor_name||'待指定'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="mode==='/hr/departments'" text @click="showDepartment(row)">查看员工</el-button><el-button v-if="mode==='/admin/supervisors'&&row.supervisor_user_id" text @click="unassign(row)">解除主管</el-button></template></el-table-column></el-table></template>
<template v-else-if="isEmployees||isUsers||mode==='/hr/positions'"><div class="v3-toolbar"><el-input v-if="mode!=='/hr/positions'" v-model="search" clearable :placeholder="isUsers?'姓名／用户名／工号':'员工姓名'" @change="resetFilters"/><el-input v-if="isEmployees" v-model="employeeNo" placeholder="精确工号" clearable @change="resetFilters"/><el-select v-model="department" clearable placeholder="全部部门" @change="resetFilters"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select><el-select v-if="isEmployees" v-model="positionFilter" clearable placeholder="全部职位" @change="resetFilters"><el-option v-for="p in positions" :key="p.id" :value="p.id" :label="`${p.name} / ${p.grade}`"/></el-select><el-select v-if="isEmployees" v-model="status" clearable placeholder="在职状态" @change="resetFilters"><el-option value="ACTIVE" label="在职"/><el-option value="LEFT" label="离职"/></el-select><el-select v-if="isUsers" v-model="roleFilter" clearable placeholder="全部角色" @change="resetFilters"><el-option v-for="(label,key) in roles" :key="key" :label="label" :value="key"/></el-select><el-select v-if="isUsers" v-model="activeFilter" clearable placeholder="账号状态" @change="resetFilters"><el-option label="启用" value="true"/><el-option label="停用" value="false"/></el-select><el-button v-if="isEmployees" type="primary" @click="open('employee')">新增员工</el-button><el-button v-if="mode==='/hr/positions'" type="primary" @click="open('position')">新增职位</el-button></div>
<div v-if="isEmployees" class="v3-toolbar"><el-button @click="download('/employees/import-template')">下载导入模板</el-button><label class="el-button"><span>导入 Excel</span><input aria-label="导入 Excel" type="file" accept=".xlsx" hidden @change="upload"/></label><el-button @click="download('/employees/export')">按筛选导出</el-button><span class="v3-note">建档自动开户 · 默认密码 Aa123 · 保存后提示实际登录名</span></div>
<el-table :data="rows"><el-table-column v-if="isUsers" prop="username" label="登录用户名" min-width="140"/><el-table-column prop="employee_no" v-if="isEmployees||isUsers" label="工号"/><el-table-column prop="name" :label="mode==='/hr/positions'?'职位名称':'姓名'"/><el-table-column v-if="mode==='/hr/positions'" prop="code" label="职位编号"/><el-table-column label="部门"><template #default="{row}">{{row.department_name||departments.find(d=>d.id===row.department_id)?.name||'独立系统账号'}}</template></el-table-column><el-table-column v-if="isEmployees" prop="position_name" label="职位"/><el-table-column v-if="!isUsers" prop="grade" label="职级"/><el-table-column v-if="isEmployees" prop="hire_date" label="入职日期"/><el-table-column v-if="isEmployees" prop="phone" label="联系电话" min-width="130"/><el-table-column v-if="isEmployees" prop="base_salary" label="税前月基本工资（元）" min-width="170"/><el-table-column v-if="isUsers" label="角色"><template #default="{row}">{{roles[row.role]}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{isUsers?(row.is_active?'启用':'停用'):mode==='/hr/positions'?(row.is_active?'有效':'停用'):row.status==='ACTIVE'?'在职':'离职'}}</template></el-table-column><el-table-column v-if="isUsers" label="员工状态"><template #default="{row}">{{row.employment_status==='ACTIVE'?'在职':row.employment_status==='LEFT'?'离职':'独立系统账号'}}</template></el-table-column><el-table-column v-if="isUsers" label="停用原因"><template #default="{row}">{{row.disabled_reason==='EMPLOYEE_LEFT'?'员工离职，自动停用':row.disabled_reason==='REHIRE_PENDING_ADMIN'?'已复职，等待管理员启用':row.disabled_reason||'—'}}</template></el-table-column><el-table-column v-if="isUsers||isEmployees" prop="left_date" label="离职日期"/><el-table-column label="操作" min-width="210"><template #default="{row}"><template v-if="isUsers"><el-button text @click="showUser(row)">历史</el-button><template v-if="row.role!=='SYS_ADMIN'"><el-button text @click="open('role',row)" :disabled="!row.is_active||row.employment_status!=='ACTIVE'">角色</el-button><el-button text @click="open('username',row)">登录名</el-button><el-button text @click="open('reset',row)">重置密码</el-button><el-button v-if="row.is_active" text @click="open('disable',row)">停用</el-button><el-button v-else text @click="enable(row)" :disabled="row.employment_status!=='ACTIVE'">启用</el-button></template></template><template v-else><el-button text @click="open(isEmployees?'employee':'position',row)">编辑</el-button><EmployeeDetails v-if="isEmployees" :employee="row"/><EmployeeLifecycle v-if="isEmployees" :employee="row" @changed="load"/></template></template></el-table-column></el-table>
<el-pagination class="v3-pagination" layout="prev,pager,next,total" :total="total" :page-size="20" v-model:current-page="page" @current-change="load"/><el-card v-if="receipt.length" class="v3-section"><h3>逐行导入回执</h3><el-table :data="receipt"><el-table-column prop="row" label="行号"/><el-table-column prop="employee_no" label="工号"/><el-table-column label="结果"><template #default="{row}">{{row.success?'成功':'失败'}}</template></el-table-column><el-table-column prop="username" label="实际登录名"/><el-table-column prop="reason" label="说明"/></el-table></el-card></template>
<el-table v-else-if="mode==='/admin/audit-logs'" :data="rows"><el-table-column prop="created_at" label="时间"/><el-table-column prop="actor_user_id" label="操作用户"/><el-table-column prop="action" label="操作"/><el-table-column prop="target_type" label="对象"/><el-table-column prop="target_id" label="对象编号"/><el-table-column prop="summary" label="说明"/></el-table>
<V3Dashboard v-else-if="mode==='/hr/dashboard'"/><V3Business v-else :mode="mode"/>
<el-dialog v-model="dialog" :title="({employee:'员工档案',bootstrap:'初始化首位 HR',position:'职位与职级',password:'修改密码',role:'角色授权',username:'修改登录名',reset:'重置密码',disable:'停用账号'} as any)[kind]" width="560px" destroy-on-close><el-form ref="formRef" :model="form" label-position="top" class="v3-form" @submit.prevent="submit"><template v-if="['employee','bootstrap'].includes(kind)"><el-form-item label="工号" prop="employee_no" :rules="required('工号')"><el-input v-model="form.employee_no"/></el-form-item><el-form-item label="员工姓名" prop="name" :rules="required('姓名')"><el-input v-model="form.name"/></el-form-item><el-form-item label="所属部门" prop="department_id" :rules="required('部门')"><el-select v-model="form.department_id" @change="form.position_id=undefined"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="职位" prop="position_id" :rules="kind==='employee'?required('职位'):[]"><el-select v-model="form.position_id" clearable placeholder="选择已有职位"><el-option v-for="p in eligiblePositions" :key="p.id" :value="p.id" :label="`${p.name} / ${p.grade}`"/></el-select></el-form-item><template v-if="kind==='bootstrap'&&!form.position_id"><el-form-item label="初始化职位名称" prop="position_name" :rules="required('职位名称')"><el-input v-model="form.position_name"/></el-form-item><el-form-item label="职级" prop="grade" :rules="required('职级')"><el-input v-model="form.grade"/></el-form-item></template><el-form-item label="入职日期" prop="hire_date" :rules="required('入职日期')"><el-date-picker v-model="form.hire_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="税前月基本工资（元）" prop="base_salary"><el-input v-model="form.base_salary" placeholder="例如 9500.00"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remarks" type="textarea"/></el-form-item></template>
<template v-if="kind==='position'"><el-form-item label="职位编号" prop="code" :rules="required('编号')"><el-input v-model="form.code"/></el-form-item><el-form-item label="职位名称" prop="name" :rules="required('名称')"><el-input v-model="form.name"/></el-form-item><el-form-item label="所属部门" prop="department_id" :rules="required('部门')"><el-select v-model="form.department_id"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="职级" prop="grade" :rules="required('职级')"><el-input v-model="form.grade"/></el-form-item><el-form-item label="职位有效"><el-switch v-model="form.is_active"/></el-form-item></template>
<template v-if="kind==='password'||kind==='reset'"><el-form-item v-if="kind==='password'" label="旧密码" prop="old_password" :rules="required('旧密码')"><el-input v-model="form.old_password" type="password" show-password/></el-form-item><el-form-item label="新密码" prop="new_password" :rules="required('新密码')"><el-input v-model="form.new_password" type="password" show-password maxlength="128"/></el-form-item><el-form-item v-if="kind==='password'" label="确认新密码" prop="confirm_password" :rules="required('确认密码')"><el-input v-model="form.confirm_password" type="password" show-password/></el-form-item><p class="v3-note">须同时含 ASCII 大写字母、小写字母和数字。修改后撤销已有登录会话。</p></template>
<el-form-item v-if="kind==='role'" label="角色" prop="role" :rules="required('角色')"><el-select v-model="form.role"><el-option v-for="r in ['EMPLOYEE','SUPERVISOR','HR']" :key="r" :value="r" :label="roles[r]"/></el-select><p class="v3-note">角色变更保留用户名、密码和业务历史，并撤销旧会话。主管还需配置部门关系。</p></el-form-item><el-form-item v-if="kind==='username'" label="登录用户名" prop="username" :rules="required('用户名')"><el-input v-model="form.username"/></el-form-item><el-form-item v-if="kind==='disable'" label="停用原因" prop="reason" :rules="required('停用原因')"><el-input v-model="form.reason" type="textarea"/></el-form-item><div class="dialog-actions"><el-button @click="dialog=false">取消</el-button><el-button type="primary" native-type="submit">保存</el-button></div></el-form></el-dialog>
<el-dialog :model-value="!!detail" :title="detail?.title" width="760px" @close="detail=null"><el-table :data="detail?.data||[]"><template v-if="detail?.kind==='department'"><el-table-column prop="employee_no" label="工号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="department_name" label="部门"/><el-table-column prop="position_name" label="职位"/><el-table-column prop="grade" label="职级"/><el-table-column prop="hire_date" label="入职日期"/></template><template v-else><el-table-column label="人事事件"><template #default="{row}">{{row.event_type==='LEFT'?'离职':'复职'}}</template></el-table-column><el-table-column prop="event_date" label="日期"/><el-table-column prop="note" label="说明"/></template></el-table></el-dialog>
</main></template>
